const steps=[{"kicker": "00 / THE MISSION", "title": "One planet. Three intelligences.", "body": "LUNARIS connects personal climate adaptation, sustainable everyday decisions, and city-scale environmental opportunity. Lumi helps visitors navigate them; the Action Network provides a pathway for participation.", "cta": "Explore the three-layer architecture", "href": "/#intelligence-map", "tag": "THREE LAYERS / ONE PLATFORM", "caveat": "This is a connected product vision, not a claim that every feature automatically shares live data."}, {"kicker": "01 / PERSONAL INTELLIGENCE", "title": "Understand the day you are stepping into.", "body": "HeatShield compares forecast-based activity windows against duration and exposure preferences. Its construction-worker extension explains UAE heat-work rules in English, Bangla and Arabic.", "cta": "Open HeatShield", "href": "/app/#heatshield", "tag": "HEATSHIELD / WORKER HEAT", "caveat": "Forecast-based planning and policy information; not personalized medical clearance or live SMS alerts."}, {"kicker": "02 / CHOICES", "title": "Turn good intentions into trade-offs.", "body": "GreenMiles compares transport choices; FoodPrint supports ingredient/product exploration and now links to Fridge Brain. WattFlow evaluates household energy scenarios and links to a climate-resilience self-check.", "cta": "Explore Choices", "href": "/app/#choices", "tag": "GREENMILES / FOODPRINT / WATTFLOW", "caveat": "Emissions factors and environmental estimates depend on their stated sources and assumptions."}, {"kicker": "03 / WALLET", "title": "Save money. Understand emissions.", "body": "Carbon & Cost Wallet makes a manual, transparent comparison of commute costs and estimated operational emissions, showing AED and CO₂e differences together.", "cta": "Open Carbon & Cost Wallet", "href": "/app/wallet/", "tag": "MONEY + CLIMATE", "caveat": "No bank connection or transaction access; some emissions factors are non-UAE proxies."}, {"kicker": "04 / HOME & FOOD", "title": "Adapt at home. Waste less food.", "body": "Fridge Brain prioritizes user-entered ingredients and dates; Home Resilience examines shade, overheating, water entry and electrical concerns. Climate Insurance introduces questions to ask about potential coverage.", "cta": "Open Fridge Brain", "href": "/app/foodprint-fridge/", "tag": "FRIDGE / HOME / INSURANCE", "caveat": "No camera recognition, automated building inspection, food-safety assessment or insurance quotes."}, {"kicker": "05 / CITY INTELLIGENCE", "title": "See your city as a place to improve.", "body": "The Dubai Action Atlas displays curated neighborhood opportunity concepts spanning cooling, greenery, biodiversity and resource efficiency. It is a starting point for investigation rather than a map of verified interventions.", "cta": "Open Dubai Action Atlas", "href": "/app/action-atlas/", "tag": "NEIGHBORHOODS / OPPORTUNITIES", "caveat": "Neighborhood proposals are not independently confirmed satellite-detected project sites."}, {"kicker": "06 / ACTION STUDIO", "title": "Move from a concern to a scenario.", "body": "Explore an illustrative shade-corridor scenario and adjust assumptions. Compare the hypothetical intervention area before interpreting any benefit; evidence and uncertainty remain visible.", "cta": "Open Action & Resilience Lab", "href": "/app/cop31-lab/", "tag": "SCENARIOS / EVIDENCE", "caveat": "The calculator does not predict measured temperature reductions."}, {"kicker": "07 / THE RESEARCH", "title": "Discover Dubai’s thermal paradox.", "body": "The research case cites published findings about differences between daytime and nighttime urban heat. A reproducible NASA POWER pipeline is included to evaluate atmospheric estimates and simple baselines.", "cta": "Read the Dubai case study", "href": "/app/action-atlas/dubai-heat-case/", "tag": "DUBAI / HEAT STUDY", "caveat": "Published research is not a measurement by LUNARIS. Verify completed NASA outputs in the production repository."}, {"kicker": "08 / MEET LUMI", "title": "Ask better environmental questions.", "body": "Lumi is the environmental guide across this ecosystem. The packaged baseline includes a bounded guide; the production Groq integration must be merged from the live repository and independently verified.", "cta": "Open Lumi", "href": "/app/#home", "tag": "LUMI / GUIDED EXPLANATIONS", "caveat": "Never present unavailable tool outputs or unverified predictions as facts."}, {"kicker": "09 / FROM INSIGHT TO ACTION", "title": "Let intelligence lead somewhere.", "body": "The complete journey connects climate awareness, personal and household decisions, neighborhood evidence and interest in collective action. Next: validate local conditions and evaluate interventions with real participants.", "cta": "Explore community Action", "href": "/app/action-atlas/", "tag": "UNDERSTAND → DECIDE → PARTICIPATE", "caveat": "Expressions of interest are not completed environmental interventions or verified impact."}];let active=0;const $=x=>document.querySelector(x);const menu=$('#step-menu');steps.forEach((step,index)=>{const b=document.createElement('button');b.className='step';b.type='button';b.innerHTML='<small>'+step.kicker.split(' / ')[0]+'</small><span class="step-name">'+step.title+'</span>';b.addEventListener('click',()=>select(index));menu.append(b)});function select(index){active=Math.max(0,Math.min(steps.length-1,index));const s=steps[active];document.querySelectorAll('.step').forEach((el,i)=>{if(i===active)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('#kicker').textContent=s.kicker;$('#step-title').textContent=s.title;$('#description').textContent=s.body;$('#tag').textContent=s.tag;$('#caveat').textContent=s.caveat;$('#go').textContent=s.cta+' ↗';$('#go').href=s.href;$('#counter').textContent=String(active+1).padStart(2,'0')+' / '+String(steps.length).padStart(2,'0');$('#progress').style.width=((active+1)/steps.length*100)+'%';$('#prev').disabled=active===0;$('#next').textContent=active===steps.length-1?'Start again ↺':'Next →';history.replaceState(null,'','#step-'+(active+1));}$('#prev').addEventListener('click',()=>select(active-1));$('#next').addEventListener('click',()=>select(active===steps.length-1?0:active+1));document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')select(active+1);if(e.key==='ArrowLeft')select(active-1)});const h=location.hash.match(/^#step-(\d+)$/);select(h?Number(h[1])-1:0);